     1→import { useMemo } from "react";
     2→import { useParams } from "react-router-dom";
     3→import { Loader2 } from "lucide-react";
     4→import { useTranslation } from "react-i18next";
     5→import { PageWrapper } from "@/components/layout";
     6→import { WorkspaceHeader } from "@/components/workspace";
     7→import { useLocalWorkspaces } from "@/hooks/use-workspaces";
     8→import { resolveHeaderSegments } from "@/navigation/page-index";
     9→import { buildColdStartBreadcrumb, registry } from "@/navigation/navigate";
    10→import { useDesktopRouting } from "@/hooks/use-desktop-routing";
    11→import { PageAppGrid } from "./components/page-app-grid";
    12→
    13→export function WorkspaceAppsPage() {
    14→  const { t } = useTranslation();
    15→  const { workspaceId } = useParams<{ workspaceId: string }>();
    16→  const { getWorkspace, isLoading } = useLocalWorkspaces();
    17→  const { currentStack } = useDesktopRouting();
    18→
    19→  const workspace = workspaceId ? getWorkspace(workspaceId) : undefined;
    20→
    21→  const segments = useMemo(() => {
    22→    if (!workspaceId) {
    23→      return [];
    24→    }
    25→
    26→    const url = registry.build("/workspace/:workspaceId/pages", { workspaceId });
    27→    const stack = buildColdStartBreadcrumb(url);
    28→
    29→    return resolveHeaderSegments({
    30→      stack: currentStack,
    31→      fallback: stack.slice(1).map((item) => ({
    32→        id: item.id,
    33→        label: item.label,
    34→        href: item.href ?? "#",
    35→        icon: item.icon,
    36→        meta: item.meta,
    37→      })),
    38→    });
    39→  }, [currentStack, workspaceId]);
    40→
    41→  if (isLoading || !workspace) {
    42→    return (
    43→      <PageWrapper className="flex flex-col h-full">
    44→        <div className="flex items-center justify-center h-full">
    45→          <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
    46→        </div>
    47→      </PageWrapper>
    48→    );
    49→  }
    50→
    51→  return (
    52→    <PageWrapper className="flex flex-col h-full">
    53→      <WorkspaceHeader
    54→        workspace={workspace}
    55→        segments={segments}
    56→        showRefresh={false}
    57→        showRemove={false}
    58→      />
    59→      <div className="min-h-0 flex-1 bg-background">
    60→        <div className="border-b px-6 py-4">
    61→          <h1 className="text-lg font-semibold">{t("page.pages", "Pages")}</h1>
    62→        </div>
    63→        <div className="min-h-0 h-[calc(100%-65px)]">
    64→          <PageAppGrid
    65→            workspaceId={workspace.id}
    66→            workspacePath={workspace.path}
    67→          />
    68→        </div>
    69→      </div>
    70→    </PageWrapper>
    71→  );
    72→}
    73→
    74→export default WorkspaceAppsPage;
