     8→import { useState, useMemo, useCallback, useEffect, useRef } from "react";
     9→import { AnimatePresence, motion } from "framer-motion";
    10→import { useTranslation } from "react-i18next";
    11→import { Plus, Loader2, X } from "lucide-react";
    12→import { cn } from "@/lib/utils";
    13→import {
    14→  AlertDialog,
    15→  AlertDialogAction,
    16→  AlertDialogCancel,
    17→  AlertDialogContent,
    18→  AlertDialogDescription,
