    45→// Component
    46→// =============================================================================
    47→
    48→export function PageAppGrid({ workspaceId, workspacePath }: PageAppGridProps) {
    49→  const { t } = useTranslation();
    50→  const { openWorkspacePage } = useDesktopRouting();
    51→  const { data: pages, isLoading, error } = usePages(workspacePath);
    52→  const deletePageMutation = useDeletePage();
    53→
    54→  // Dialog states
    55→  const [pageToDelete, setPageToDelete] = useState<PageConfig | null>(null);
    56→  const [createDialogOpen, setCreateDialogOpen] = useState(false);
    57→  const [createParentSlug, setCreateParentSlug] = useState<string | undefined>(undefined);
    58→  const [permissionsPage, setPermissionsPage] = useState<PageConfig | null>(null);
    59→
    60→  // Folder overlay state
    61→  const [openFolder, setOpenFolder] = useState<PageTreeNode | null>(null);
    62→  const [folderOrigin, setFolderOrigin] = useState<{ x: number; y: number } | null>(null);
    63→
    64→  // Build tree
    65→  const pageTree = useMemo(() => {
    66→    if (!pages || pages.length === 0) return [];
    67→    return buildPageTree(pages);
    68→  }, [pages]);
    69→
    70→  // Handlers
    71→  const handlePageClick = useCallback(
    72→    (page: PageConfig) => {
    73→      openWorkspacePage(workspaceId, page.slug, {
    74→        title: page.name,
    75→        icon: page.icon,
    76→      });
    77→    },
    78→    [openWorkspacePage, workspaceId]
    79→  );
    80→
    81→  const handleOpenInNewTab = useCallback(
    82→    (page: PageConfig) => {
    83→      openWorkspacePage(workspaceId, page.slug, {
    84→        openMode: "new-tab",
    85→        title: page.name,
    86→        icon: page.icon,
    87→      });
    88→    },
    89→    [openWorkspacePage, workspaceId]
    90→  );
    91→
    92→  const handleDeletePage = async () => {
    93→    if (!pageToDelete) return;
    94→    try {
    95→      await deletePageMutation.mutateAsync({
    96→        workspacePath,
    97→        slug: pageToDelete.slug,
    98→      });
    99→      toast.success(t("page.deleteSuccess"));
   100→    } catch (err) {
   101→      console.error("Failed to delete page:", err);
   102→      toast.error(t("page.deleteFailed"));
   103→    } finally {
   104→      setPageToDelete(null);
   105→    }
   106→  };
   107→
   108→  const handleCreateSubpage = useCallback((parentSlug: string) => {
   109→    setCreateParentSlug(parentSlug);
   110→    setCreateDialogOpen(true);
   111→  }, []);
   112→
   113→  const handleCreatePage = useCallback(() => {
   114→    setCreateParentSlug(undefined);
   115→    setCreateDialogOpen(true);
   116→  }, []);
   117→
   118→  const handleCreateSuccess = useCallback(
   119→    (slug: string) => {
   120→      const page = pages?.find((item) => item.slug === slug);
   121→      openWorkspacePage(workspaceId, slug, {
   122→        title: page?.name ?? slug.split("/").filter(Boolean).pop() ?? slug,
   123→        icon: page?.icon,
   124→      });
   125→    },
   126→    [openWorkspacePage, pages, workspaceId]
   127→  );
   128→
   129→  const handleNodeClick = useCallback(
   130→    (node: PageTreeNode, e?: React.MouseEvent) => {
   131→      if (node.children.length > 0) {
   132→        // Capture viewport-relative origin for folder animation
   133→        if (e) {
   134→          const target = (e.currentTarget as HTMLElement);
   135→          const iconRect = target.getBoundingClientRect();
   136→          setFolderOrigin({
   137→            x: iconRect.left + iconRect.width / 2,
   138→            y: iconRect.top + iconRect.height / 2,
   139→          });
   140→        }
   141→        setOpenFolder(node);
   142→      } else {
   143→        openWorkspacePage(workspaceId, node.page.slug, {
   144→          title: node.page.name,
   145→          icon: node.page.icon,
   146→        });
   147→      }
   148→    },
   149→    [openWorkspacePage, workspaceId]
   150→  );
   151→
   152→  // Loading
   153→  if (isLoading) {
   154→    return (
   155→      <div className="flex items-center justify-center h-full">
   156→        <Loader2
   157→          className="h-6 w-6 animate-spin"
   158→          style={{ color: "rgba(255, 255, 255, 0.5)" }}
   159→        />
   160→      </div>
   161→    );
   162→  }
   163→
   164→  // Error
   165→  if (error) {
   166→    const errorMessage = error instanceof Error ? error.message : t("common.error");
   167→    return (
   168→      <div className="flex items-center justify-center h-full">
   169→        <p
   170→          className="text-sm"
   171→          style={{ color: "rgba(255, 255, 255, 0.5)" }}
   172→        >
   173→          {errorMessage}
   174→        </p>
   175→      </div>
   176→    );
   177→  }
   178→
   179→  return (
   180→    <>
   181→      <div className="h-full overflow-y-auto px-8 py-6">
   182→        {pageTree.length === 0 ? (
   183→          /* Empty state */
   184→          <div className="flex flex-col items-center justify-center h-full gap-4">
   185→            <button
   186→              type="button"
   187→              onClick={handleCreatePage}
   188→              className={cn(
   189→                "w-[60px] h-[60px] rounded-[14px] flex items-center justify-center",
   190→                "transition-transform duration-150 ease-out",
   191→                "hover:scale-105 active:scale-95"
   192→              )}
   193→              style={{
   194→                backgroundColor: "rgba(255, 255, 255, 0.12)",
   195→                border: "2px dashed rgba(255, 255, 255, 0.3)",
   196→              }}
   197→            >
   198→              <Plus className="h-6 w-6" style={{ color: "rgba(255, 255, 255, 0.6)" }} />
   199→            </button>
   200→            <p
   201→              className="text-sm"
   202→              style={{ color: "rgba(255, 255, 255, 0.5)" }}
   203→            >
   204→              {t("page.noPages")}
   205→            </p>
   206→          </div>
   207→        ) : (
   208→          /* Page grid */
   209→          <div className="grid grid-cols-[repeat(auto-fill,minmax(80px,1fr))] gap-y-5 gap-x-2 justify-items-center">
   210→            {pageTree.map((node) => (
   211→              <div
   212→                key={node.page.slug}
   213→                onClick={(e) => handleNodeClick(node, e)}
   214→              >
   215→                <PageAppIcon
   216→                  node={node}
   217→                  workspacePath={workspacePath}
   218→                  onClick={() => {/* handled by parent wrapper for position tracking */}}
   219→                  onOpenInNewTab={handleOpenInNewTab}
   220→                  onCreateSubpage={handleCreateSubpage}
   221→                  onDeleteClick={setPageToDelete}
   222→                  onPermissionsClick={setPermissionsPage}
   223→                />
   224→              </div>
   225→            ))}
   226→            {/* Add page button */}
   227→            <button
   228→              type="button"
   229→              onClick={handleCreatePage}
   230→              className={cn(
   231→                "flex flex-col items-center gap-1.5 w-[76px]",
   232→                "transition-transform duration-150 ease-out",
   233→                "hover:scale-105 active:scale-95"
   234→              )}
   235→            >
   236→              <div
   237→                className="w-[60px] h-[60px] rounded-[14px] flex items-center justify-center"
   238→                style={{
   239→                  backgroundColor: "rgba(255, 255, 255, 0.1)",
   240→                  border: "2px dashed rgba(255, 255, 255, 0.25)",
   241→                }}
   242→              >
   243→                <Plus className="h-6 w-6" style={{ color: "rgba(255, 255, 255, 0.5)" }} />
   244→              </div>
   245→              <span
   246→                className="text-[11px]"
   247→                style={{ color: "rgba(255, 255, 255, 0.5)" }}
   248→              >
   249→                {t("page.createPage")}
   250→              </span>
   251→            </button>
   252→          </div>
   253→        )}
   254→      </div>
   255→
   256→      {/* Folder overlay - fixed position covers entire viewport including dock */}
   257→      <AnimatePresence>
   258→        {openFolder && (
   259→          <FolderOverlay
   260→            folder={openFolder}
   261→            origin={folderOrigin}
   262→            workspacePath={workspacePath}
   263→            onPageClick={handlePageClick}
   264→            onOpenInNewTab={handleOpenInNewTab}
   265→            onCreateSubpage={handleCreateSubpage}
   266→            onDeleteClick={setPageToDelete}
   267→            onPermissionsClick={setPermissionsPage}
   268→            onClose={() => setOpenFolder(null)}
   269→          />
   270→        )}
   271→      </AnimatePresence>
   272→
   273→      {/* Delete confirmation */}
   274→      <AlertDialog
   275→        open={!!pageToDelete}
   276→        onOpenChange={(open) => !open && setPageToDelete(null)}
   277→      >
   278→        <AlertDialogContent>
   279→          <AlertDialogHeader>
   280→            <AlertDialogTitle>
   281→              {t("common.delete")} &quot;{pageToDelete?.name}&quot;?
   282→            </AlertDialogTitle>
   283→            <AlertDialogDescription>
   284→              {t("workspace.deleteConfirmDescription", {
   285→                name: pageToDelete?.name,
   286→              })}
   287→            </AlertDialogDescription>
   288→          </AlertDialogHeader>
   289→          <AlertDialogFooter>
   290→            <AlertDialogCancel disabled={deletePageMutation.isPending}>
   291→              {t("common.cancel")}
   292→            </AlertDialogCancel>
   293→            <AlertDialogAction
   294→              onClick={handleDeletePage}
   295→              disabled={deletePageMutation.isPending}
   296→              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
   297→            >
   298→              {deletePageMutation.isPending
   299→                ? t("common.deleting")
   300→                : t("common.delete")}
   301→            </AlertDialogAction>
   302→          </AlertDialogFooter>
   303→        </AlertDialogContent>
   304→      </AlertDialog>
   305→
   306→      {/* Create dialog */}
   307→      <CreatePageDialog
   308→        open={createDialogOpen}
   309→        onOpenChange={setCreateDialogOpen}
   310→        workspacePath={workspacePath}
   311→        parentSlug={createParentSlug}
   312→        onSuccess={handleCreateSuccess}
   313→      />
   314→
   315→      {/* Permissions dialog */}
   316→      <PagePermissionsDialog
   317→        open={!!permissionsPage}
   318→        onOpenChange={(open) => !open && setPermissionsPage(null)}
   319→        page={permissionsPage}
   320→        workspacePath={workspacePath}
   321→      />
   322→    </>
   323→  );
   324→}
