   326→// =============================================================================
   327→// Folder Overlay
   328→// =============================================================================
   329→
   330→interface FolderOverlayProps {
   331→  folder: PageTreeNode;
   332→  origin: { x: number; y: number } | null;
   333→  workspacePath: string;
   334→  onPageClick: (page: PageConfig) => void;
   335→  onOpenInNewTab: (page: PageConfig) => void;
   336→  onCreateSubpage: (parentSlug: string) => void;
   337→  onDeleteClick: (page: PageConfig) => void;
   338→  onPermissionsClick: (page: PageConfig) => void;
   339→  onClose: () => void;
   340→}
   341→
   342→function FolderOverlay({
   343→  folder,
   344→  origin,
   345→  workspacePath,
   346→  onPageClick,
   347→  onOpenInNewTab,
   348→  onCreateSubpage,
   349→  onDeleteClick,
   350→  onPermissionsClick,
   351→  onClose,
   352→}: FolderOverlayProps) {
   353→  const { t } = useTranslation();
   354→  const overlayRef = useRef<HTMLDivElement>(null);
   355→
   356→  // Close on Escape
   357→  useEffect(() => {
   358→    const handleKeyDown = (e: KeyboardEvent) => {
   359→      if (e.key === "Escape") onClose();
   360→    };
   361→    window.addEventListener("keydown", handleKeyDown);
   362→    return () => window.removeEventListener("keydown", handleKeyDown);
   363→  }, [onClose]);
   364→
   365→  // Close when clicking outside
   366→  const handleBackdropClick = useCallback(
   367→    (e: React.MouseEvent) => {
   368→      if (e.target === overlayRef.current) {
   369→        onClose();
   370→      }
   371→    },
   372→    [onClose]
   373→  );
   374→
   375→  const handleChildClick = useCallback(
   376→    (node: PageTreeNode) => {
   377→      onPageClick(node.page);
   378→      onClose();
   379→    },
   380→    [onClose, onPageClick]
   381→  );
   382→
   383→  // Calculate offset from viewport center to icon position (for iPad-style expand animation)
   384→  const offsetX = origin ? origin.x - window.innerWidth / 2 : 0;
   385→  const offsetY = origin ? origin.y - window.innerHeight / 2 : 0;
   386→
   387→  return (
   388→    <motion.div
   389→      ref={overlayRef}
   390→      className="fixed inset-0 z-50 flex items-center justify-center"
   391→      style={{
   392→        background: origin
   393→          ? `radial-gradient(600px circle at ${origin.x}px ${origin.y}px, rgba(0, 0, 0, 0.15) 0%, rgba(0, 0, 0, 0.6) 100%)`
   394→          : "radial-gradient(ellipse at center, rgba(0, 0, 0, 0.15) 0%, rgba(0, 0, 0, 0.6) 100%)",
   395→        backdropFilter: "blur(12px) saturate(120%)",
   396→        WebkitBackdropFilter: "blur(12px) saturate(120%)",
   397→      }}
   398→      initial={{ opacity: 0 }}
   399→      animate={{ opacity: 1 }}
   400→      exit={{ opacity: 0 }}
   401→      transition={{ duration: 0.2 }}
   402→      onClick={handleBackdropClick}
   403→    >
   404→      <motion.div
   405→        className="relative max-w-sm w-full mx-4 rounded-2xl p-5"
   406→        style={{
   407→          backgroundColor: "rgba(255, 255, 255, 0.15)",
   408→          backdropFilter: "blur(40px)",
   409→          WebkitBackdropFilter: "blur(40px)",
   410→          border: "1px solid rgba(255, 255, 255, 0.2)",
   411→          boxShadow: "0 20px 60px rgba(0, 0, 0, 0.3)",
   412→        }}
   413→        initial={{ scale: 0.4, opacity: 0, x: offsetX * 0.5, y: offsetY * 0.5 }}
   414→        animate={{ scale: 1, opacity: 1, x: 0, y: 0 }}
   415→        exit={{ scale: 0.4, opacity: 0, x: offsetX * 0.5, y: offsetY * 0.5 }}
   416→        transition={{ type: "spring", stiffness: 400, damping: 30 }}
   417→      >
   418→        {/* Close button */}
   419→        <button
   420→          type="button"
   421→          onClick={onClose}
   422→          className="absolute top-3 right-3 p-1 rounded-full hover:bg-white/10 transition-colors"
   423→        >
   424→          <X className="h-4 w-4" style={{ color: "rgba(255, 255, 255, 0.6)" }} />
   425→        </button>
   426→
   427→        {/* Folder name */}
   428→        <h3
   429→          className="text-base font-semibold text-center mb-4"
   430→          style={{
   431→            color: "rgba(255, 255, 255, 0.9)",
   432→            textShadow: "0 1px 3px rgba(0, 0, 0, 0.4)",
   433→          }}
   434→        >
   435→          {folder.page.name}
   436→        </h3>
   437→
   438→        {/* Child pages grid */}
   439→        <div className="grid grid-cols-[repeat(auto-fill,minmax(80px,1fr))] gap-y-5 gap-x-2 justify-items-center">
   440→          {folder.children.map((child) => (
   441→            <PageAppIcon
   442→              key={child.page.slug}
   443→              node={child}
   444→              workspacePath={workspacePath}
   445→              onClick={() => handleChildClick(child)}
   446→              onOpenInNewTab={onOpenInNewTab}
   447→              onCreateSubpage={onCreateSubpage}
   448→              onDeleteClick={onDeleteClick}
   449→              onPermissionsClick={onPermissionsClick}
   450→            />
   451→          ))}
   452→          {/* Add subpage button */}
   453→          <button
   454→            type="button"
   455→            onClick={() => {
   456→              onCreateSubpage(folder.page.slug);
   457→              onClose();
   458→            }}
   459→            className={cn(
   460→              "flex flex-col items-center gap-1.5 w-[76px]",
   461→              "transition-transform duration-150 ease-out",
   462→              "hover:scale-105 active:scale-95"
   463→            )}
   464→          >
   465→            <div
   466→              className="w-[60px] h-[60px] rounded-[14px] flex items-center justify-center"
   467→              style={{
   468→                backgroundColor: "rgba(255, 255, 255, 0.1)",
   469→                border: "2px dashed rgba(255, 255, 255, 0.25)",
   470→              }}
   471→            >
   472→              <Plus className="h-5 w-5" style={{ color: "rgba(255, 255, 255, 0.5)" }} />
   473→            </div>
   474→            <span
   475→              className="text-[11px]"
   476→              style={{ color: "rgba(255, 255, 255, 0.5)" }}
   477→            >
   478→              {t("page.createSubpage")}
   479→            </span>
   480→          </button>
   481→        </div>
   482→      </motion.div>
   483→    </motion.div>
   484→  );
   485→}
